    $nameM = [regex]::Match($text, 'versionName\s+"([^"]+)"')
  }
  if (-not $codeM.Success -or -not $nameM.Success) { throw "parse fail $BuildGradle" }
  $newCode = [int]$codeM.Groups[1].Value + 1
  $parts = @($nameM.Groups[1].Value -split '\.')
  while ($parts.Count -lt 3) { $parts += '0' }
  $newName = "$($parts[0]).$($parts[1]).$newCode"
  if ($isKts) {
    $text = [regex]::Replace($text, 'versionCode\s*=\s*\d+', "versionCode = $newCode")
    $text = [regex]::Replace($text, 'versionName\s*=\s*"[^"]+"', "versionName = `"$newName`"")
  } else {
    $text = [regex]::Replace($text, 'versionCode\s+\d+', "versionCode $newCode")
    $text = [regex]::Replace($text, 'versionName\s+"[^"]+"', "versionName `"$newName`"")
  }
  Write-Utf8NoBom $BuildGradle $text
  return @{ Name = $newName; Code = $newCode }
}

function Stage-Artifacts([string]$GradleDir, [string]$DestDir, [string]$BaseName, [string]$Version, [bool]$IsNative) {
  New-Item -ItemType Directory -Force -Path $DestDir | Out-Null
  if ($IsNative) {
    $apkDir = Join-Path $GradleDir 'app\build\outputs\apk\release'
    $aabDir = Join-Path $GradleDir 'app\build\outputs\bundle\release'
  } else {
    $apkDir = Join-Path $GradleDir 'app\build\outputs\apk\release'
    $aabDir = Join-Path $GradleDir 'app\build\outputs\bundle\release'
  }
  $apk = Get-ChildItem $apkDir -Filter '*.apk' -ErrorAction Stop | Where-Object { $_.Name -notmatch 'unsigned|debug' } | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  if (-not $apk) {
    $apk = Get-ChildItem $apkDir -Filter '*.apk' -ErrorAction Stop | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  }
  $aab = Get-ChildItem $aabDir -Filter '*.aab' -ErrorAction Stop | Where-Object { $_.Name -notmatch 'unsigned|debug' } | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  if (-not $aab) {
    $aab = Get-ChildItem $aabDir -Filter '*.aab' -ErrorAction Stop | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  }
  $apkSuffix = if ($apk.Name -match 'unsigned') { '-unsigned' } else { '' }
  $aabSuffix = if ($aab.Name -match 'unsigned') { '-unsigned' } else { '' }
  $apkDest = Join-Path $DestDir ("{0}-{1}{2}.apk" -f $BaseName, $Version, $apkSuffix)
  $aabDest = Join-Path $DestDir ("{0}-{1}{2}.aab" -f $BaseName, $Version, $aabSuffix)
  Copy-Item $apk.FullName $apkDest -Force
  Copy-Item $aab.FullName $aabDest -Force
  return @{ Apk = $apkDest; Aab = $aabDest }
}

